set-variable.value:
@{
        // The public APIM operation path is not what the Bedrock Runtime
        // backend receives. Build the one-encoded wire path from the matched
        // modelId instead of signing context.Request.Url.Path.
        var modelId = (string)context.Variables["ai-hub-bedrock-model-id"];
        var escapedModelId = System.Uri.EscapeDataString(modelId);
        return "/model/" + escapedModelId + "/converse";
      }

@{
        // AWS non-S3 SigV4 signs one URI-encoding pass over the wire path,
        // preserving only path separators. This deliberately turns %3A in
        // the forwarded model segment into %253A in CanonicalURI.
        var wirePath = (string)context.Variables["ai-hub-bedrock-wire-path"];
        return string.Join("/", wirePath.Split('/').Select(segment => System.Uri.EscapeDataString(segment)));
      }

@{
        // AWS SigV4 canonical query construction requires every individual
        // value of a (possibly repeated) query parameter to be separately
        // URI-encoded, then all encoded pairs sorted by encoded key and,
        // for equal keys, by encoded value -- not by the pre-joined
        // "key=value" text, which does not sort equivalently.
        var queryDict = context.Request.Url.Query;
        var encodedPairs = new List<KeyValuePair<string, string>>();
        if (queryDict != null)
        {
          foreach (var kvp in queryDict)
          {
            var encodedKey = System.Uri.EscapeDataString(kvp.Key);
            foreach (var rawValue in kvp.Value)
            {
              var encodedValue = System.Uri.EscapeDataString(rawValue ?? "");
              encodedPairs.Add(new KeyValuePair<string, string>(encodedKey, encodedValue));
            }
          }
        }
        var orderedPairs = encodedPairs
          .OrderBy(p => p.Key, StringComparer.Ordinal)
          .ThenBy(p => p.Value, StringComparer.Ordinal);
        return string.Join("&", orderedPairs.Select(p => p.Key + "=" + p.Value));
      }

@{
        // Hash the actual raw request bytes (not a re-encoded string copy)
        // so X-Amz-Content-Sha256 and the Authorization signature both
        // reflect exactly what is forwarded to the backend.
        var bodyBytes = context.Request.Body.As<byte[]>(preserveContent: true);
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
          var hash = sha256.ComputeHash(bodyBytes);
          return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
      }

rewrite-uri.template:
@{
        var path = (string)context.Variables["ai-hub-bedrock-wire-path"];
        var query = (string)context.Variables["ai-hub-bedrock-canonical-query"];
        return string.IsNullOrEmpty(query) ? path : path + "?" + query;
      }

set-header.value:
@{
        var accessKey = "{{ai-hub-bedrock-access-key}}";
        var secretKey = "{{ai-hub-bedrock-secret-key}}";
        var region = "{{ai-hub-bedrock-region}}";
        var service = "bedrock";

        var method = context.Request.Method;
        var host = (string)context.Variables["ai-hub-bedrock-host"];

        // Non-S3 SigV4 signs the canonical path derived from the forwarded
        // wire path, while the canonical query is sent as constructed.
        var path = (string)context.Variables["ai-hub-bedrock-canonical-path"];
        var canonicalQueryString = (string)context.Variables["ai-hub-bedrock-canonical-query"];

        var amzDate = ((DateTime)context.Variables["ai-hub-bedrock-now"]).ToString("yyyyMMddTHHmmssZ");
        var dateStamp = ((DateTime)context.Variables["ai-hub-bedrock-now"]).ToString("yyyyMMdd");

        // Reuse the single raw-byte payload hash computed above for both
        // X-Amz-Content-Sha256 and the signature.
        var hashedPayload = (string)context.Variables["ai-hub-bedrock-payload-hash"];

        var headers = context.Request.Headers;
        var canonicalHeaderList = new List<string[]>();

        // SigV4 canonical headers require lowercase header *names*, but
        // header *values* must be normalized (internal whitespace runs
        // collapsed to a single space, outer whitespace trimmed) without
        // otherwise altering their case or content.
        var contentType = headers.GetValueOrDefault("Content-Type", "");
        if (!string.IsNullOrEmpty(contentType))
        {
          var normalizedContentType = System.Text.RegularExpressions.Regex.Replace(contentType, @"\s+", " ").Trim();
          canonicalHeaderList.Add(new[] { "content-type", normalizedContentType });
        }

        canonicalHeaderList.Add(new[] { "host", host });

        foreach (var header in headers)
        {
          var name = header.Key.ToLowerInvariant();
          if (name == "x-amz-content-sha256" || name == "x-amz-date")
          {
            continue;
          }
          if (name.StartsWith("x-amz-"))
          {
            // Every repeated value of the same header must be retained and
            // combined into one canonical, comma-joined value -- reading
            // only the first value would silently drop signed data that
            // the backend still receives.
            var normalizedValues = header.Value.Select(v => System.Text.RegularExpressions.Regex.Replace(v ?? "", @"\s+", " ").Trim());
            var combinedValue = string.Join(",", normalizedValues);
            canonicalHeaderList.Add(new[] { name, combinedValue });
          }
        }
        canonicalHeaderList.Add(new[] { "x-amz-content-sha256", hashedPayload });
        canonicalHeaderList.Add(new[] { "x-amz-date", amzDate });

        var canonicalHeadersOrdered = canonicalHeaderList.OrderBy(h => h[0], StringComparer.Ordinal);
        var canonicalHeaders = string.Join("\n", canonicalHeadersOrdered.Select(h => h[0] + ":" + h[1])) + "\n";
        var signedHeaders = string.Join(";", canonicalHeadersOrdered.Select(h => h[0]));

        var canonicalRequest = method + "\n" + path + "\n" + canonicalQueryString + "\n" + canonicalHeaders + "\n" + signedHeaders + "\n" + hashedPayload;
        string hashedCanonicalRequest;
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
          var hash = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(canonicalRequest));
          hashedCanonicalRequest = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }

        var credentialScope = dateStamp + "/" + region + "/" + service + "/aws4_request";
        var stringToSign = "AWS4-HMAC-SHA256\n" + amzDate + "\n" + credentialScope + "\n" + hashedCanonicalRequest;

        byte[] kSecret = System.Text.Encoding.UTF8.GetBytes("AWS4" + secretKey);
        byte[] kDate, kRegion, kService, kSigning;
        using (var h1 = new System.Security.Cryptography.HMACSHA256(kSecret))
        {
          kDate = h1.ComputeHash(System.Text.Encoding.UTF8.GetBytes(dateStamp));
        }
        using (var h2 = new System.Security.Cryptography.HMACSHA256(kDate))
        {
          kRegion = h2.ComputeHash(System.Text.Encoding.UTF8.GetBytes(region));
        }
        using (var h3 = new System.Security.Cryptography.HMACSHA256(kRegion))
        {
          kService = h3.ComputeHash(System.Text.Encoding.UTF8.GetBytes(service));
        }
        using (var h4 = new System.Security.Cryptography.HMACSHA256(kService))
        {
          kSigning = h4.ComputeHash(System.Text.Encoding.UTF8.GetBytes("aws4_request"));
        }

        string signature;
        using (var hmac = new System.Security.Cryptography.HMACSHA256(kSigning))
        {
          var sigBytes = hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(stringToSign));
          signature = BitConverter.ToString(sigBytes).Replace("-", "").ToLowerInvariant();
        }

        return "AWS4-HMAC-SHA256 Credential=" + accessKey + "/" + credentialScope + ", SignedHeaders=" + signedHeaders + ", Signature=" + signature;
      }
